// Build a small record out of whatever was POSTed to the webhook.
// $input.first().json.body holds the parsed request body.
const body = $input.first().json.body ?? {};
const stamp = new Date().toISOString();

return [
  {
    json: {
      receivedAt: stamp,
      // Safe filename: colons are legal on Linux but awkward to type.
      fileName: `hello-${stamp.replace(/[:.]/g, '-')}.json`,
      payload: body,
    },
  },
];
